import json

def round4(x):
    return round(x, 4)

def main():
    # Load input
    with open('/app/data/input.json', 'r') as f:
        input_data = json.load(f)

    training_samples = input_data['training_samples']
    test_samples = input_data['test_samples']
    model_config = input_data['model_config']

    state_categories = model_config['state_categories']
    feature_weights = model_config['feature_weights']
    sensor_priority = model_config['sensor_priority']

    states = sorted(state_categories.keys())
    primary_sensors = ['motor_temperature_c', 'vibration_amplitude_mm', 'current_consumption_a', 'position_error_mm']
    non_primary_sensors = ['velocity_rpm', 'torque_nm', 'encoder_reading', 'operational_hours']
    all_sensors = primary_sensors + non_primary_sensors

    sensor_to_range_key = {
        'motor_temperature_c': 'temperature_range',
        'vibration_amplitude_mm': 'vibration_range',
        'current_consumption_a': 'current_range',
        'position_error_mm': 'position_error_range'
    }

    state_ranges = {}
    for state in states:
        state_ranges[state] = {}
        for sensor in primary_sensors:
            range_key = sensor_to_range_key[sensor]
            lo, hi = state_categories[state][range_key]
            state_ranges[state][sensor] = (lo, hi)

    category_weights = [0.4, 0.3, 0.2, 0.1]
    critical_state = 'critical'
    normal_state = 'normal'

    denom_map = {}
    for range_key in ['temperature_range', 'vibration_range', 'current_range', 'position_error_range']:
        denom_map[range_key] = state_categories[critical_state][range_key][1] - state_categories[normal_state][range_key][1]

    anomaly_denom_map = {}
    for range_key in ['temperature_range', 'vibration_range', 'current_range', 'position_error_range']:
        anomaly_denom_map[range_key] = state_categories[critical_state][range_key][1] - state_categories[normal_state][range_key][0]

    primary_norm_denom_map = {}
    for range_key in ['temperature_range', 'vibration_range', 'current_range', 'position_error_range']:
        primary_norm_denom_map[range_key] = state_categories[critical_state][range_key][1] - state_categories[normal_state][range_key][0]

    all_samples = training_samples + test_samples
    non_primary_min = {}
    non_primary_max = {}
    for sensor in non_primary_sensors:
        values = [s[sensor] for s in all_samples]
        non_primary_min[sensor] = min(values)
        non_primary_max[sensor] = max(values)

    hours_values = [s['operational_hours'] for s in all_samples]
    min_hours = min(hours_values)
    max_hours = max(hours_values)

    predictions = []

    for sample in all_samples:
        sample_id = sample['sample_id']
        sample_values = {s: sample[s] for s in all_sensors}

        state_scores = {}
        for state in states:
            sensor_matches = {}
            for i, sensor in enumerate(primary_sensors):
                lo, hi = state_ranges[state][sensor]
                value = sample_values[sensor]
                range_key = sensor_to_range_key[sensor]
                denom = denom_map[range_key]

                if lo <= value <= hi:
                    match = 1.0
                else:
                    if value < lo:
                        dist = lo - value
                    else:
                        dist = value - hi
                    match = max(0.0, min(1.0, 1.0 - dist / denom))
                sensor_matches[sensor] = match

            cat_score = sum(category_weights[i] * sensor_matches[primary_sensors[i]] for i in range(4))
            state_scores[state] = cat_score

        best_state = None
        best_score = None
        for state in states:
            if best_score is None or state_scores[state] > best_score:
                best_score = state_scores[state]
                best_state = state

        predicted_state = best_state
        state_match_score = round4(best_score)

        sorted_states = sorted(states, key=lambda s: (-state_scores[s], s))
        best = state_scores[sorted_states[0]]
        second = state_scores[sorted_states[1]]
        confidence = min(1.0, 0.5 + 2.0 * (best - second))
        confidence_score = round4(confidence)

        normal_ranges = state_categories[normal_state]
        anomaly_indicators = []
        for sensor in primary_sensors:
            range_key = sensor_to_range_key[sensor]
            value = sample_values[sensor]
            normal_lo = normal_ranges[range_key][0]
            normal_hi = normal_ranges[range_key][1]
            denom = anomaly_denom_map[range_key]

            if value < normal_lo or value > normal_hi:
                if value < normal_lo:
                    dist = normal_lo - value
                else:
                    dist = value - normal_hi
                severity = round4(dist / denom)
                anomaly_indicators.append({'sensor': sensor, 'severity': severity})

        priority_order = {s: i for i, s in enumerate(sensor_priority)}
        for a in anomaly_indicators:
            a['_priority'] = priority_order.get(a['sensor'], 999999)
        anomaly_indicators.sort(key=lambda x: (x['_priority'], -x['severity'], x['sensor']))
        for a in anomaly_indicators:
            del a['_priority']

        feature_contributions = {}
        if max_hours == min_hours:
            wear = 1.0
        else:
            hours = sample['operational_hours']
            wear = 1.0 + 0.3 * (hours - min_hours) / (max_hours - min_hours)

        for sensor in all_sensors:
            if sensor in primary_sensors:
                range_key = sensor_to_range_key[sensor]
                norm_lo = state_categories[normal_state][range_key][0]
                crit_hi = state_categories[critical_state][range_key][1]
                span = crit_hi - norm_lo
                value = sample_values[sensor]
                contrib = (value - norm_lo) / span if span != 0 else 0.0
            else:
                min_val = non_primary_min[sensor]
                max_val = non_primary_max[sensor]
                span = max_val - min_val
                value = sample_values[sensor]
                contrib = (value - min_val) / span if span != 0 else 0.0

            if sensor in ['motor_temperature_c', 'vibration_amplitude_mm', 'current_consumption_a']:
                contrib = contrib * wear

            contrib = max(0.0, min(1.0, contrib))
            feature_contributions[sensor] = round4(contrib)

        num_anomalies = len(anomaly_indicators)
        if num_anomalies >= 3 and predicted_state == 'normal':
            predicted_state = 'degraded'

        prediction = {
            'sample_id': sample_id,
            'predicted_state': predicted_state,
            'confidence_score': confidence_score,
            'state_match_score': state_match_score,
            'feature_contributions': {k: feature_contributions[k] for k in sorted(feature_contributions.keys())},
            'anomaly_indicators': anomaly_indicators
        }
        predictions.append(prediction)

    predictions.sort(key=lambda p: p['sample_id'])

    # Model performance
    confusion = {s: {t: 0 for t in states} for s in states}
    train_preds = [p for p in predictions if p['sample_id'].startswith('train')]
    for pred in train_preds:
        sample_id = pred['sample_id']
        true_state = None
        for ts in training_samples:
            if ts['sample_id'] == sample_id:
                true_state = ts['system_state']
                break
        predicted_state = pred['predicted_state']
        if true_state and predicted_state:
            confusion[true_state][predicted_state] += 1

    total = sum(sum(row.values()) for row in confusion.values())
    correct = sum(confusion[s][s] for s in states)
    accuracy = round4(correct / total) if total > 0 else 0.0

    precisions = []
    recalls = []
    f1s = []
    for state in states:
        tp = confusion[state][state]
        predicted_count = sum(confusion[s][state] for s in states)
        precision = tp / predicted_count if predicted_count > 0 else 0.0
        precisions.append(precision)
        actual_count = sum(confusion[state][s] for s in states)
        recall = tp / actual_count if actual_count > 0 else 0.0
        recalls.append(recall)
        f1 = 2 * precision * recall / (precision + recall) if precision + recall > 0 else 0.0
        f1s.append(f1)

    model_performance = {
        'accuracy': accuracy,
        'confusion_matrix': confusion,
        'f1_score': round4(sum(f1s) / len(f1s)),
        'precision': round4(sum(precisions) / len(precisions)),
        'recall': round4(sum(recalls) / len(recalls))
    }

    # Feature importance
    all_contribs = {sensor: [] for sensor in all_sensors}
    for pred in predictions:
        for sensor, contrib in pred['feature_contributions'].items():
            all_contribs[sensor].append(contrib)

    feature_importance_list = []
    for sensor in all_sensors:
        mean_contrib = sum(all_contribs[sensor]) / len(all_contribs[sensor])
        weight = feature_weights[sensor]
        importance = max(0.0, min(1.0, mean_contrib * weight))
        importance = round4(importance)
        feature_importance_list.append({'feature': sensor, 'importance': importance})

    feature_importance_list.sort(key=lambda x: (-x['importance'], x['feature']))

    output = {
        'predictions': predictions,
        'model_performance': model_performance,
        'feature_importance': feature_importance_list
    }

    with open('/app/data/output.json', 'w') as f:
        json.dump(output, f, separators=(',', ':'), sort_keys=True)
        f.write('\n')

if __name__ == '__main__':
    main()
